INSERT INTO public.track_tournament_result (id_tournament,id_user,id_record,time,rank,points,date_created,date_updated) VALUES($1,$2,$3,$4,1,1000,clock_timestamp(),clock_timestamp()) ON CONFLICT (id_tournament,id_user) DO UPDATE SET id_record=excluded.id_record,time=excluded.time,date_updated=excluded.date_updated WHERE excluded.time<track_tournament_result.time OR NOT zc_private.record_is_eligible(track_tournament_result.id_record) RETURNING id_tournament AS id
